Method.Source:
    [
        DataMemberAttribute,
        AifQueryTypeAttribute('_packedQuery', queryStr(METVendSiteSettingsSetupQuery))
    ]
    public str parmPackedQuery(str _packedQuery = packedQuery)
    {
        packedQuery = _packedQuery;

        return packedQuery;
